:scope {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #003366;
  --warm: #d9531e;
  --line: #e0e0e0;
  --paper: #f9f9f9;
  --font-base: 15px;
  --font-ctrl: 13px;
}

.cm-chapter {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  max-width: 1000px;
  margin: 0 auto;
  line-height: 1.6;
}

.cm-header {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 1rem;
  margin-bottom: 2rem;
}

.cm-title {
  font-size: 2rem;
  color: var(--accent);
  margin: 0 0 0.5rem 0;
}

.cm-lead {
  font-size: 1.1rem;
  color: var(--muted);
  max-width: 800px;
}

.cm-workspace {
  display: grid;
  gap: 2rem;
}

.cm-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #fff;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 4px;
}

.cm-control-group label {
  font-weight: bold;
  margin-right: 0.5rem;
  font-size: var(--font-ctrl);
}

#cluster-select {
  padding: 0.4rem;
  font-size: var(--font-ctrl);
  border: 1px solid var(--line);
  border-radius: 4px;
  min-width: 200px;
}

.cm-legend {
  display: flex;
  gap: 1rem;
  font-size: var(--font-ctrl);
}

.cm-legend-item {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.dot.western { background: #003366; }
.dot.eastern { background: #d9531e; }
.dot.southern { background: #28a745; }

.cm-visual-container {
  position: relative;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 400px;
  overflow: hidden;
}

canvas {
  max-width: 100%;
  height: auto;
}

.cm-overlay-info {
  position: absolute;
  top: 1rem;
  right: 1rem;
  background: rgba(255, 255, 255, 0.95);
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  max-width: 250px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.cm-overlay-info h3 {
  margin: 0 0 0.5rem 0;
  font-size: 1rem;
  color: var(--accent);
}

.cm-overlay-info p {
  margin: 0;
  font-size: var(--font-ctrl);
  color: var(--muted);
}

.cm-analysis-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}

.cm-card {
  background: #fff;
  padding: 1.5rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  border-left: 4px solid var(--accent);
}

.cm-card h4 {
  margin: 0 0 0.5rem 0;
  font-size: 1rem;
  color: var(--ink);
}

.cm-card p {
  font-size: var(--font-base);
  color: var(--muted);
  margin-bottom: 1rem;
}

.cm-source-btn {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.2rem 0.5rem;
  font-size: var(--font-ctrl);
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.2s;
}

.cm-source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.cm-footer {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--line);
}

.cm-methodology h4 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.cm-methodology p {
  font-size: var(--font-base);
  color: var(--muted);
  margin-bottom: 1rem;
}

javascript:
(function() {
  'use strict';

  const canvas = document.getElementById('radar-chart');
  const ctx = canvas.getContext('2d');
  const selector = document.getElementById('cluster-select');
  const infoTitle = document.getElementById('info-title');
  const infoDesc = document.getElementById('info-desc');

  // 9 个维度，顺序与论文 Figure 3(b) 一致
  const dimensions = [
    'Sparing Humans',
    'Sparing More',
    'Sparing Young',
    'Sparing Pedestrians',
    'Sparing Females',
    'Sparing Fit',
    'Sparing Lawful',
    'Sparing High Status',
    'Sparing Passengers'
  ];

  // 教学示例数据 (Z-scores)，基于 Figure 3(b) 的视觉估算
  // 注意：此处数值为相对大小示意，非原始训练权重
  const clusterData = {
    western: {
      name: '西方集群',
      desc: '包含北美及许多欧洲国家（新教、天主教和东正教文化群）。',
      scores: [0.8, 0.7, 0.6, 0.2, 0.3, 0.4, 0.3, 0.2, -0.4]
    },
    eastern: {
      name: '东方集群',
      desc: '包含许多远东国家（儒家文化群）以及伊斯兰国家。对“保幼”和“保地位”偏好较弱。',
      scores: [0.7, 0.5, 0.2, 0.2, 0.2, 0.3, 0.3, 0.1, -0.3]
    },
    southern: {
      name: '南方集群',
      desc: '主要由拉丁美洲国家组成，也包括部分受法国影响的国家。对“保女性”、“保地位”和“保幼”偏好极强。',
      scores: [0.6, 0.6, 0.8, 0.2, 0.6, 0.6, 0.3, 0.5, -0.2]
    }
  };

  const config = {
    centerX: canvas.width / 2,
    centerY: canvas.height / 2,
    radius: Math.min(canvas.width, canvas.height) / 2 - 40,
    levels: 4,
    colorWestern: '#003366',
    colorEastern: '#d9531e',
    colorSouthern: '#28a745',
    gridColor: '#e0e0e0',
    textColor: '#666666'
  };

  function drawRadar(scores, color) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const angleStep = (Math.PI * 2) / dimensions.length;

    // 绘制网格
    ctx.strokeStyle = config.gridColor;
    ctx.lineWidth = 1;
    for (let i = 1; i <= config.levels; i++) {
      const levelRadius = (config.radius / config.levels) * i;
      ctx.beginPath();
      for (let j = 0; j < dimensions.length; j++) {
        const angle = j * angleStep - Math.PI / 2;
        const x = config.centerX + Math.cos(angle) * levelRadius;
        const y = config.centerY + Math.sin(angle) * levelRadius;
        if (j === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.stroke();
    }

    // 绘制轴线
    ctx.strokeStyle = '#cccccc';
    for (let i = 0; i < dimensions.length; i++) {
      const angle = i * angleStep - Math.PI / 2;
      const x = config.centerX + Math.cos(angle) * config.radius;
      const y = config.centerY + Math.sin(angle) * config.radius;
      ctx.beginPath();
      ctx.moveTo(config.centerX, config.centerY);
      ctx.lineTo(x, y);
      ctx.stroke();

      // 标签
      const labelX = config.centerX + Math.cos(angle) * (config.radius + 20);
      const labelY = config.centerY + Math.sin(angle) * (config.radius + 20);
      ctx.fillStyle = config.textColor;
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(dimensions[i], labelX, labelY);
    }

    // 绘制数据多边形
    ctx.fillStyle = color.replace(')', ', 0.2)').replace('rgb', 'rgba').replace('#', 'rgb(');
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < dimensions.length; i++) {
      const angle = i * angleStep - Math.PI / 2;
      // 归一化分数到半径范围 (假设分数在 -1 到 1 之间)
      const normalizedScore = (scores[i] + 1) / 2; 
      const r = normalizedScore * config.radius;
      const x = config.centerX + Math.cos(angle) * r;
      const y = config.centerY + Math.sin(angle) * r;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // 绘制顶点
    ctx.fillStyle = color;
    for (let i = 0; i < dimensions.length; i++) {
      const angle = i * angleStep - Math.PI / 2;
      const normalizedScore = (scores[i] + 1) / 2;
      const r = normalizedScore * config.radius;
      const x = config.centerX + Math.cos(angle) * r;
      const y = config.centerY + Math.sin(angle) * r;
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  function updateChart() {
    const selected = selector.value;
    const data = clusterData[selected];
    let color;
    if (selected === 'western') color = config.colorWestern;
    else if (selected === 'eastern') color = config.colorEastern;
    else color = config.colorSouthern;

    drawRadar(data.scores, color);
    infoTitle.textContent = data.name;
    infoDesc.textContent = data.desc;
  }

  selector.addEventListener('change', updateChart);

  // 初始化
  updateChart();

  // 响应式调整
  window.addEventListener('resize', () => {
    // 简单重绘，实际生产环境需更复杂的 debounce 和尺寸计算
    updateChart();
  });
})();
